body.en:
Start at the `LEAK SUMMARY`: `definitely lost: 31 bytes in 4 blocks`. "Definitely lost" means no pointer to the block exists any more, so it cannot be freed by anyone. The four blocks above it each have a call chain. Read each chain from the top down to find the code, then from the bottom up to find the test:

- the top line, `malloc`, is the allocation itself;
- the next frame, `dup_string`, is our function that called `malloc`;
- then `profile_parse`, which asked for the string, with the line of the call;
- the bottom frame is the caller, `main` in profile_test.c, at the line of one particular test.

There are four records, not three, because two of the three invalid specs leak two blocks each (the name and the host). Two different `main` lines in the chains tell you which specs: the port 99999 test and the port 0 test. The missing-port spec returns before it allocates anything, so it does not appear. The common point is the `if (port < 1 || port > 65535)` check in profile_parse. It was added after the allocations, and its `free(p)` forgot the two strings that `p` owns.

patch.from:
struct profile *profile_parse(const char *spec)
{
    char name[32], host[64];
    long port;

    struct profile *p = calloc(1, sizeof *p);
    if (p == NULL) {
        return NULL;
    }
    if (sscanf(spec, "%31s %63s %ld", name, host, &port) != 3) {
        free(p);
        return NULL;
    }
    p->name = dup_string(name);
    p->host = dup_string(host);
    if (p->name == NULL || p->host == NULL) {
        free(p->name);
        free(p->host);
        free(p);
        return NULL;
    }
    if (port < 1 || port > 65535) {
        free(p);
        return NULL;
    }
    p->port = (unsigned)port;
    return p;
}

patch.to:
struct profile *profile_parse(const char *spec)
{
    char name[32], host[64];
    long port;

    struct profile *p = calloc(1, sizeof *p);
    if (p == NULL) {
        return NULL;
    }
    if (sscanf(spec, "%31s %63s %ld", name, host, &port) != 3) {
        goto fail;
    }
    if (port < 1 || port > 65535) {
        goto fail;
    }
    p->name = dup_string(name);
    p->host = dup_string(host);
    if (p->name == NULL || p->host == NULL) {
        goto fail;
    }
    p->port = (unsigned)port;
    return p;

fail:
    profile_free(p);            /* releases whatever was set so far; fields start as NULL */
    return NULL;
}
